syntax:
std::vector<T> vec; 
vec[i]; // Random access using [] operator
vec.at(i); // Bound-checked access

code_example:
#include <iostream>
#include <vector>
#include <chrono>
#include <random>
int main() {
  std::vector<int> vec(10000000);
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> distrib(0, 9999999);
  auto start = std::chrono::high_resolution_clock::now();
  for (int i = 0; i < 1000000; ++i) {
    int index = distrib(gen);
    int val = vec[index]; // Unchecked access
    //int val = vec.at(index); //Checked access.  Slower but safer.
  }
  auto end = std::chrono::high_resolution_clock::now();
  auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
  std::cout << "Time taken: " << duration.count() << " milliseconds" << std::endl;
  return 0;
}
